package com.mantou.salesdialer.contacts;
import java.util.*;import java.time.*;
public final class AttemptMetricsCheck {
 static int checks;static String id(int n){return "LOCAL-ATTEMPT-"+String.format("%064X",n);}static String target(int n){return "LOCAL-TARGET-"+String.format("%032x",n);}static AttemptMetrics.Entry e(int n,int t,long at,boolean api,String result,boolean closed){return new AttemptMetrics.Entry(id(n),target(t),at,api,result,closed);}static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static void bad(Runnable r){try{r.run();throw new AssertionError("accepted invalid metric input");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args){var rows=new ArrayList<>(List.of(e(1,1,100,true,"NO_ANSWER",false),e(2,1,110,true,"COMPLETED",false),e(3,2,120,false,"UNKNOWN",false),e(4,3,130,false,"",false),e(5,2,140,true,"UNKNOWN",true)));var s=AttemptMetrics.summarize(rows,0,Long.MAX_VALUE);ok(s.authorizedAttempts==5,"authorization count");ok(s.distinctTargets==3,"different targets and retries separate");ok(s.apiAccepted==3,"only confirmed API receipts");ok(s.pending==2,"unknown and no-result pending");ok(s.manualNoAnswer==1&&s.manualCompleted==1,"separate manual outcomes");ok(s.manualUnknown==2&&s.closedUnknown==1,"closed unknown retains uncertainty");ok(s.actualOutgoing==null&&s.actualConnected==null,"API/manual completion never fabricates platform proof");rows.clear();ok(s.authorizedAttempts==5,"immutable summary");var empty=AttemptMetrics.summarize(List.of(),0,Long.MAX_VALUE);ok(empty.authorizedAttempts==0&&empty.distinctTargets==0&&empty.actualOutgoing==null&&empty.actualConnected==null,"empty has no inferred carrier evidence");
 var window=AttemptMetrics.summarize(List.of(e(1,1,100,true,"",false),e(2,2,110,false,"",false),e(3,3,120,false,"",false)),100,120);ok(window.authorizedAttempts==2&&window.distinctTargets==2,"inclusive start exclusive end");long[] day=AttemptMetrics.beijingDay(LocalDate.of(2026,10,19));ok(day[0]==Instant.parse("2026-10-18T16:00:00Z").toEpochMilli()&&day[1]-day[0]==86400000,"Beijing day independent of host timezone");ok(AttemptMetrics.summarize(List.of(e(1,1,day[0]-1,true,"",false),e(2,2,day[0],true,"",false),e(3,3,day[1]-1,true,"",false),e(4,4,day[1],true,"",false)),day[0],day[1]).authorizedAttempts==2,"midnight cohorts");
 bad(()->AttemptMetrics.summarize(null,0,100));bad(()->AttemptMetrics.summarize(List.of(),10,10));bad(()->AttemptMetrics.summarize(List.of(),-1,10));var duplicate=e(1,1,100,true,"",false);bad(()->AttemptMetrics.summarize(List.of(duplicate,duplicate),0,200));bad(()->e(1,1,100,true,"COMPLETED",true));bad(()->e(1,1,100,false,"CONNECTED",false));bad(()->new AttemptMetrics.Entry("19900009401",target(1),100,false,"",false));
 List<AttemptMetrics.Entry> capacity=new ArrayList<>();for(int i=1;i<=201;i++)capacity.add(e(i,1,100+i,true,"NO_ANSWER",false));s=AttemptMetrics.summarize(capacity,0,Long.MAX_VALUE);ok(s.distinctTargets==1&&s.authorizedAttempts==201&&s.apiAccepted==201&&s.manualNoAnswer==201,"201 retries not 201 different numbers or limit");ok(s.actualOutgoing==null&&s.actualConnected==null,"recording receipts not actual phone events");System.out.println("AttemptMetricsCheck passed "+checks+" assertions");
 }
}
